// v1=hex(HMAC_SHA256(secret, `${ts}.${payload}`))
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const req = $input.first().json;
const timestamp = req.headers['x-lendloop-timestamp'];
const signature = String(req.headers['x-lendloop-signature'] || '');
const payload = req.body && req.body.payload;
const reject = (reason) => [{ json: { valid: false, reason } }];

if (!timestamp || !signature || typeof payload !== 'string') return reject('missing');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale');
const expected = 'v1=' + crypto
  .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
  .update(`${timestamp}.${payload}`)
  .digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad_signature');

const event = JSON.parse(payload);
if (event.kind !== 'loan-event' || event.version !== 1) return reject('unsupported');
return [{ json: { valid: true, event } }];

// Mock channel: logs the message instead of sending it.
const e = $json.event;
const { toolName, startDate, endDate, counterpartFirstName: who } = e.loan;
const lines = {
  'loan.requested': `${who} would like to borrow your ${toolName} from ${startDate} to ${endDate}.`,
  'loan.approved': `${who} approved your request for the ${toolName} (${startDate} to ${endDate}).`,
  'loan.declined': `${who} cannot lend the ${toolName} for ${startDate} to ${endDate} this time.`,
  'loan.cancelled': e.recipient.role === 'borrower'
    ? `your loan of the ${toolName} (${startDate} to ${endDate}) was cancelled.`
    : `${who} cancelled the request for your ${toolName}.`,
  'loan.returned': `${who} marked the ${toolName} as returned. Thanks for borrowing!`,
};
const text = `Hi ${e.recipient.firstName}, ${lines[e.type]}`;
if (e.recipient.email.endsWith('@fail.test')) throw new Error('Simulated delivery failure');
console.log(`[LendLoop notify] to=${e.recipient.email} event=${e.eventId} :: ${text}`);
return { json: { writeBack: { type: 'notification.result', eventId: e.eventId, status: 'notified' } } };

const event = $('Verify signature').first().json.event;
const detail = String($json.error || 'notification failed').slice(0, 200);
return { json: { writeBack: { type: 'notification.result', eventId: event.eventId, status: 'failed', detail } } };

// HTTP retries reuse this timestamp, so they must happen within 5 minutes.
const crypto = require('crypto');
const payload = JSON.stringify($json.writeBack);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto
  .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
  .update(`${timestamp}.${payload}`)
  .digest('hex');
return { json: { ...$json, signed: { payload, timestamp, signature } } };
